program_template:
module main;
import io;
buffer Bytes:u8;
result Encoded{ok:Bytes,err:i64}
result Changed{ok:bool,err:i64}
result Decoded{ok:bool,err:i64}
fn work(heap:allocator)->Decoded{
 let literal=INPUT;
 let mut bytes=try acquire_buffer<Encoded>(heap,1024);
 borrow literal[0..len(literal)] as view{
  let mut i=0u64;
  while i<len_slice(view){discard try append_buffer<Changed>(bytes,read_slice(view,i));i+=1u64;}
 }
 return json_decode::<Decoded>(heap,bytes,1024);
}
fn main(heap:allocator)->i64{
 match work(heap){
  Decoded.ok(discard)=>{discard io::put(48u8);return 0;},
  Decoded.err(code)=>{discard io::put(u8(48+code));return 0;}
 }
}
